select
  'data-and-quantitative-methods',
  null,
  'Data and Quantitative Methods',
  'Data and Quantitative Methods',
  'This course teaches students to use data and quantitative methods to answer political science and policy questions. Students learn research design, measurement, data sources, reproducible workflow, data cleaning, exploratory analysis, inference, regression, surveys, experiments, causal inference, prediction, text analysis, ethics, and evidence communication.',
  $dqmtjson${"slug": "data-and-quantitative-methods", "title": "Data and Quantitative Methods", "description": "This course teaches students to use data and quantitative methods to answer political science and policy questions. Students learn research design, measurement, data sources, reproducible workflow, data cleaning, exploratory analysis, inference, regression, surveys, experiments, causal inference, prediction, text analysis, ethics, and evidence communication.", "topics": [{"id": "498d6157-6f7b-4a50-820f-cce4e66de168", "type": "topic", "title": "Research design, measurement, and quantitative questions", "description": "Frame empirical political and policy questions as testable, measurable, ethically defensible research designs.", "children": [{"id": "d7ad3764-07d4-40c8-938a-84096d1057b7", "type": "subtopic", "title": "Research questions and theory", "children": [{"id": "22dc0f26-e724-4816-ab6d-d1da0295e020", "type": "concept", "title": "Conceptual questions versus empirical questions"}, {"id": "08a54d7b-06eb-4ece-b6b3-250d7e040cfc", "type": "concept", "title": "Theory, mechanisms, and hypotheses"}, {"id": "79794f55-1728-4a6c-a9b6-47c30ad672dc", "type": "concept", "title": "Units of analysis and scope conditions"}], "description": "Students learn to turn broad political questions into empirical designs that can actually be tested."}, {"id": "746d9ffe-35fc-4c4e-8992-4ac463621010", "type": "subtopic", "title": "Measurement and operationalization", "children": [{"id": "4896b439-e803-4a20-b83a-e9bfb154bbd6", "type": "concept", "title": "Concepts, indicators, indexes, and scales"}, {"id": "38509761-ad25-4194-9fe9-d223b793c7e8", "type": "concept", "title": "Reliability, validity, and construct mismatch"}, {"id": "c3f356f0-a626-4308-bbca-b6c9d6a0cd3b", "type": "concept", "title": "Measurement bias and comparability"}], "description": "This subtopic shows how abstract concepts become variables and why measurement choices matter."}, {"id": "efebc549-f505-402c-963d-f93912586186", "type": "subtopic", "title": "Design logic and threats", "children": [{"id": "92883ffe-ef46-4089-b6e6-9dd2fb117e53", "type": "concept", "title": "Internal and external validity"}, {"id": "383010c7-4262-4cf1-be79-fdad2e227f02", "type": "concept", "title": "Selection bias, confounding, and reverse causality"}, {"id": "ffdc22a5-3f11-4d63-958b-24c804e29a74", "type": "concept", "title": "Ethical and feasibility constraints"}], "description": "Students learn to anticipate the weaknesses of a design before looking at results."}]}, {"id": "3484edad-3371-4cba-be61-b998e1830e0e", "type": "topic", "title": "Data sources, data structures, and reproducible workflow", "description": "Find, import, organize, document, and reproduce analyses using political, administrative, survey, and open data.", "children": [{"id": "8a642f3f-9cf9-4bb1-b3c6-091f73746fa0", "type": "subtopic", "title": "Political and policy data sources", "children": [{"id": "a6b0a5fe-b230-4665-a839-2457070d83bc", "type": "concept", "title": "Surveys, administrative data, election returns, text corpora, and geospatial data"}, {"id": "dd34055c-ee4c-4ed9-ba80-0098eb72a6d1", "type": "concept", "title": "ICPSR, ANES, V-Dem, World Bank, Census, Data.gov"}, {"id": "c8448175-391e-4b9a-8688-92e4eb750373", "type": "concept", "title": "Metadata, codebooks, and provenance"}], "description": "Students learn where credible datasets come from and how source decisions shape analysis."}, {"id": "acde0763-8e48-4c89-a135-591bf31aac6e", "type": "subtopic", "title": "Data structures", "children": [{"id": "ebed6881-227c-4d1d-840e-3d3135696d28", "type": "concept", "title": "Rows, columns, identifiers, keys, and joins"}, {"id": "5e8685f5-d1f0-4131-99a9-1edde7f7fef8", "type": "concept", "title": "Cross-sectional, panel, time-series, hierarchical, and network data"}, {"id": "d078bb84-4d87-4751-b135-d51f1429d31f", "type": "concept", "title": "Wide versus long formats"}], "description": "This subtopic teaches the grammar of datasets before modeling begins."}, {"id": "47314e29-269a-4231-9450-362d5469f02b", "type": "subtopic", "title": "Reproducible workflow", "children": [{"id": "f9cf22fe-d2e6-4cb8-9707-ec62688f1313", "type": "concept", "title": "Project folders, scripts, notebooks, and literate reports"}, {"id": "82fd869e-3ca1-451f-9b9e-531e10356769", "type": "concept", "title": "Version control concepts and seeds"}, {"id": "2054779b-2af4-44f5-ac41-4af4bd0006c4", "type": "concept", "title": "Data dictionaries, README files, and replication packages"}], "description": "Students learn to make their work inspectable, rerunnable, and defensible."}]}, {"id": "78b3c90e-5f93-436b-b067-1a5b83402587", "type": "topic", "title": "Data cleaning, wrangling, missingness, and measurement error", "description": "Turn messy real-world data into auditable analysis datasets while tracking bias and uncertainty.", "children": [{"id": "059570cb-bec9-431b-8656-0be0420ef7df", "type": "subtopic", "title": "Importing and cleaning data", "children": [{"id": "3a27ac4a-32cc-4ac3-9bb5-1ff592eb0335", "type": "concept", "title": "CSV, Excel, APIs, and web data basics"}, {"id": "f2e4b9d8-8dd2-4390-987c-67e4e4f16f58", "type": "concept", "title": "Types, dates, labels, factor levels, and duplicates"}, {"id": "6882a2ee-6a48-4790-be5f-64f13d4b2ce2", "type": "concept", "title": "Tidy data principles"}], "description": "Students learn the ordinary but crucial work that makes analysis trustworthy."}, {"id": "6a7a4e80-184a-43b7-a0f8-707012003361", "type": "subtopic", "title": "Missingness and outliers", "children": [{"id": "fdddd6f2-d07e-473c-9d86-9809cbadb44d", "type": "concept", "title": "MCAR, MAR, MNAR intuition"}, {"id": "f6951dd8-b936-44e7-bcc6-faf0da908124", "type": "concept", "title": "Listwise deletion, imputation awareness, and sensitivity checks"}, {"id": "d324bbf9-d401-4301-b399-b6cfc578c0d2", "type": "concept", "title": "Outliers, leverage, and anomalous records"}], "description": "This subtopic teaches students to diagnose data problems instead of hiding them."}, {"id": "fcda0904-69b5-4896-9175-38c703ffd7bd", "type": "subtopic", "title": "Measurement error and bias", "children": [{"id": "32b30366-2dd0-49a2-8106-8452f2efac60", "type": "concept", "title": "Administrative data limitations"}, {"id": "1103e2f1-c0c0-4170-bb00-3e7e3ec9a70f", "type": "concept", "title": "Survey nonresponse and coverage error"}, {"id": "23523e30-6d62-44d7-868a-df1c08ffe56c", "type": "concept", "title": "Audit trails and cleaning logs"}], "description": "Students learn that bad data can produce precise-looking wrong answers."}]}, {"id": "a8110a17-4194-4d33-9728-e0ad5d2d97ab", "type": "topic", "title": "Descriptive statistics, exploratory analysis, and visualization", "description": "Summarize distributions, relationships, groups, and trends with effective statistical graphics.", "children": [{"id": "97453ecf-d2b2-4991-9855-737c62ace7cc", "type": "subtopic", "title": "Summary statistics", "children": [{"id": "ecfd3479-f263-4b95-8cde-dbb68bcc3e75", "type": "concept", "title": "Mean, median, mode, variance, standard deviation, IQR"}, {"id": "a338a2f6-fe80-457e-acfe-40ea8f4f11da", "type": "concept", "title": "Rates, proportions, percentages, and per-capita measures"}, {"id": "933aeb32-e1a7-4390-ba9d-5fc24e225532", "type": "concept", "title": "Weighted summaries"}], "description": "Students learn to describe variables before modeling them."}, {"id": "c414e716-288d-4c8e-b8ca-1e2f1d8d5777", "type": "subtopic", "title": "Exploratory data analysis", "children": [{"id": "c7d43686-32d6-4a27-ab28-5dfe2917686a", "type": "concept", "title": "Distributions, skew, clusters, and anomalies"}, {"id": "1d63e069-37b3-4396-90a7-49fc6589d8ec", "type": "concept", "title": "Cross-tabs and grouped summaries"}, {"id": "a3551ba2-4905-4e6f-b26b-61e0d10943e3", "type": "concept", "title": "EDA as a pre-modeling diagnostic"}], "description": "This subtopic uses patterns to generate questions and catch mistakes."}, {"id": "fa3b6e2c-c488-4a67-bd59-ce3f45073e83", "type": "subtopic", "title": "Visualization principles", "children": [{"id": "a2121fa2-0a6b-41a9-8bd1-cbb5bceb26bb", "type": "concept", "title": "Histograms, density plots, boxplots, scatterplots, line charts, maps"}, {"id": "496afea7-9958-44f4-892d-15060e0fab4a", "type": "concept", "title": "Encoding, scale, labels, and uncertainty"}, {"id": "0a1c6699-762a-41de-9d1e-bb69dcf0db49", "type": "concept", "title": "Accessibility and avoiding misleading graphics"}], "description": "Students learn to make graphs that reveal evidence rather than decorate it."}]}, {"id": "a39c8804-ec0d-4c29-b282-e5489d61c24c", "type": "topic", "title": "Probability, sampling, uncertainty, and statistical inference", "description": "Understand sampling error, standard errors, confidence intervals, hypothesis tests, and uncertainty.", "children": [{"id": "09347181-c48e-42c5-84a1-d8ce8d01e0d6", "type": "subtopic", "title": "Probability foundations", "children": [{"id": "f2ce8a15-45b6-49d2-a6be-7fb42154f7f8", "type": "concept", "title": "Random variables and distributions"}, {"id": "0fe754a1-b9cc-4463-af0f-4b81ad0ab5b6", "type": "concept", "title": "Expected value and variance"}, {"id": "2ec73b19-3e3e-4caf-9889-9a317c88e039", "type": "concept", "title": "Conditional probability and Bayes intuition"}], "description": "Students learn the language of uncertainty used in statistics and policy risk."}, {"id": "eb01b36b-b258-44a7-8799-f71ef1d90c9c", "type": "subtopic", "title": "Sampling and standard errors", "children": [{"id": "543b0179-21e4-4d88-a485-993da427867e", "type": "concept", "title": "Sampling frames and sampling designs"}, {"id": "36df437b-f9ae-42b8-b03f-aae8038ea48a", "type": "concept", "title": "Central limit theorem intuition"}, {"id": "b0227fde-40b4-4b67-b54a-9554a3bfe22d", "type": "concept", "title": "Standard errors, margins of error, and design effects"}], "description": "This subtopic connects samples to populations and explains why estimates vary."}, {"id": "05696773-df5d-47c7-8b9a-c9eb27bf5678", "type": "subtopic", "title": "Inference and hypothesis testing", "children": [{"id": "76346fb2-704e-4a75-83e9-52be5e9f8838", "type": "concept", "title": "Confidence intervals"}, {"id": "edd366a9-8b02-4f18-a7dd-6eaf4b95f323", "type": "concept", "title": "Null hypotheses and p-values"}, {"id": "dc5651aa-3386-493d-8e87-3fef6d98b678", "type": "concept", "title": "Statistical versus substantive significance"}], "description": "Students learn to interpret statistical evidence without ritual or overclaiming."}]}, {"id": "58070c56-b19a-45bd-bfdb-adbbfdc69673", "type": "topic", "title": "Comparing groups, contingency tables, and bivariate relationships", "description": "Analyze group differences, proportions, associations, and simple models before moving to complex designs.", "children": [{"id": "443120e9-2855-4b4b-8101-735b79047682", "type": "subtopic", "title": "Group comparisons", "children": [{"id": "ee3f1f90-5c49-4c49-b22a-71a3ee9e864d", "type": "concept", "title": "Difference in means and proportions"}, {"id": "b3f07744-d3f2-4f76-9a47-2e2ba6d46208", "type": "concept", "title": "t-tests, ANOVA intuition, and nonparametric awareness"}, {"id": "b3bd1b05-c5c5-440d-91ce-bf22df9121b3", "type": "concept", "title": "Effect sizes and uncertainty"}], "description": "Students learn first-pass tools for whether groups differ meaningfully."}, {"id": "c4e4923c-becd-41aa-a813-ca8ca81f8331", "type": "subtopic", "title": "Categorical data", "children": [{"id": "745bcdb5-a8ea-4c93-9b11-bdf5cccb8d53", "type": "concept", "title": "Contingency tables"}, {"id": "a82b3f2f-f352-4fd3-bae4-2ece3aacbab3", "type": "concept", "title": "Chi-square tests"}, {"id": "c401fca5-a3f1-463f-980c-8114bd769996", "type": "concept", "title": "Risk ratios, odds ratios, and interpretation"}], "description": "This subtopic supports analysis of parties, race/ethnicity, institutions, attitudes, and outcomes."}, {"id": "5d2c89f3-f597-44c1-ae28-addbd3d88c39", "type": "subtopic", "title": "Bivariate relationships", "children": [{"id": "01609902-ee88-44ab-9c53-9a56b5e0303a", "type": "concept", "title": "Correlation"}, {"id": "5f5e3898-0b84-44d6-b86f-1500b81ee7b9", "type": "concept", "title": "Simple regression"}, {"id": "1872710b-5c7b-4acc-80c2-7ea70706cd13", "type": "concept", "title": "Spurious relationships and lurking variables"}], "description": "Students learn to visualize and estimate simple associations."}]}, {"id": "d0914685-1f52-4a45-91e3-85071a4c3fb6", "type": "topic", "title": "Regression modeling, diagnostics, and interpretation", "description": "Estimate and interpret linear, logistic, and multiple regression models with attention to assumptions and confounding.", "children": [{"id": "9e6c955e-40bc-41d6-8bf3-e58ebb3f491d", "type": "subtopic", "title": "Multiple regression", "children": [{"id": "610d7c1d-829e-44cf-a09c-eeed561bdb84", "type": "concept", "title": "OLS model specification"}, {"id": "6e09e02b-40c0-4a69-9a5d-ecb0857677e0", "type": "concept", "title": "Coefficients, standard errors, confidence intervals"}, {"id": "f2594fd5-26b0-438e-9759-b7c0e76b1f84", "type": "concept", "title": "Controls, interactions, transformations, and fixed effects awareness"}], "description": "Students learn to model relationships while adjusting for other variables."}, {"id": "9554357b-e3d4-4a58-9f58-80b70704278c", "type": "subtopic", "title": "Model diagnostics", "children": [{"id": "b3940722-d5c8-41d1-895e-2d2296c2d545", "type": "concept", "title": "Residuals, nonlinearity, heteroskedasticity, multicollinearity"}, {"id": "6894be3a-1811-438c-a4b3-91a98e708b73", "type": "concept", "title": "Influential points and leverage"}, {"id": "5d145a81-6abb-4a0f-97dc-1137fcc157ce", "type": "concept", "title": "Robust standard errors and clustered data awareness"}], "description": "This subtopic teaches students to inspect whether a model is credible."}, {"id": "355f07db-7656-4f96-bad4-2f2a09c47a49", "type": "subtopic", "title": "Limited dependent variables", "children": [{"id": "f469b5cf-cda6-4aca-abb4-f04941a92de6", "type": "concept", "title": "Logistic regression"}, {"id": "e668ef97-d6d1-44a7-99c4-ef7b7c6d33ec", "type": "concept", "title": "Predicted probabilities and marginal effects"}, {"id": "0d5a8e2b-9255-4a86-9b5c-8e70315d9e58", "type": "concept", "title": "Classification versus explanation"}], "description": "Students learn models for binary and categorical outcomes common in politics."}]}, {"id": "d37bb90d-741b-4b79-986a-eba3b77f142c", "type": "topic", "title": "Surveys, experiments, and natural experiments", "description": "Design and evaluate survey data, randomized experiments, field experiments, and naturally occurring policy variation.", "children": [{"id": "605d087f-3536-4a77-9053-3e2983a1116d", "type": "subtopic", "title": "Survey design and analysis", "children": [{"id": "d73b2187-53c0-4f24-b80d-df2baa2a7d04", "type": "concept", "title": "Question wording and order effects"}, {"id": "948357ac-9791-403e-8b1f-33238b3e87fc", "type": "concept", "title": "Sampling, weights, and nonresponse"}, {"id": "970f6a54-7209-4c2b-91eb-278df5942458", "type": "concept", "title": "Likert items, indexes, and survey experiments"}], "description": "Students learn to work with opinion and behavioral data responsibly."}, {"id": "8343b6d3-7f53-45c7-968d-ec512222d385", "type": "subtopic", "title": "Randomized experiments", "children": [{"id": "dac26667-6597-4dca-9b5f-afd872269c79", "type": "concept", "title": "Random assignment and balance"}, {"id": "31bebca7-0a7f-422c-9622-0b276049cf4a", "type": "concept", "title": "Treatment, control, compliance, and attrition"}, {"id": "700a8847-baf5-4904-9b1b-3fa03f632b5e", "type": "concept", "title": "Field, lab, and survey experiments"}], "description": "This subtopic introduces the strongest design for causal identification when feasible."}, {"id": "5d095388-2b3f-44dd-afd3-a8d2edcf002c", "type": "subtopic", "title": "Natural experiments", "children": [{"id": "766a6099-38c4-4992-bc2e-89cd500b23a3", "type": "concept", "title": "As-if random assignment"}, {"id": "3e3dd8c3-3c5a-4b7c-ab97-22f04adfc96b", "type": "concept", "title": "Design credibility"}, {"id": "50b0fcf9-3335-4f78-b599-2acf93bfdb70", "type": "concept", "title": "Placebo and balance checks"}], "description": "Students learn how institutional rules or events can create quasi-random variation."}]}, {"id": "a8286002-e0d9-4b63-8608-8d97e99d00b2", "type": "topic", "title": "Causal inference for observational policy data", "description": "Apply potential outcomes, matching, fixed effects, difference-in-differences, regression discontinuity, and instrumental variables.", "children": [{"id": "69b554e8-0ac5-4e00-9b2b-6be52d60fc9e", "type": "subtopic", "title": "Potential outcomes and counterfactuals", "children": [{"id": "91a372ec-f309-43c9-b2cc-49712309df3b", "type": "concept", "title": "Treatment and control potential outcomes"}, {"id": "93a084e1-173b-41af-9669-8ba12f406e8a", "type": "concept", "title": "Average treatment effects"}, {"id": "e36c1a49-dbee-4603-9339-19c5450effc6", "type": "concept", "title": "Identification assumptions"}], "description": "Students learn the core language of causal effects."}, {"id": "96f4b0c7-ea57-47be-8db3-34944f932810", "type": "subtopic", "title": "Quasi-experimental designs", "children": [{"id": "0d62c8e6-4fd0-4721-9037-45d5e3979924", "type": "concept", "title": "Difference-in-differences"}, {"id": "8f7a0986-fc32-4b46-a846-6d91b2976025", "type": "concept", "title": "Regression discontinuity"}, {"id": "f2821bff-1453-4c26-a64f-194c89442564", "type": "concept", "title": "Instrumental variables"}, {"id": "644eeec8-713a-410a-a748-70e674e53008", "type": "concept", "title": "Matching, weighting, and panel fixed effects"}], "description": "This subtopic develops the major tools used in policy and political science."}, {"id": "e5d376bb-5c51-45e8-8e63-02dee72f0213", "type": "subtopic", "title": "Causal claims and limitations", "children": [{"id": "8020db8e-643a-4f11-bf41-94f34f4e89a4", "type": "concept", "title": "Parallel trends, exclusion restrictions, bandwidth choice"}, {"id": "642b0974-457f-4153-965c-1a42f28ad7ab", "type": "concept", "title": "Sensitivity analysis"}, {"id": "19c0f55c-1fe2-4071-800b-b6ed0cd573b8", "type": "concept", "title": "External validity and policy generalization"}], "description": "Students learn to state what an analysis can and cannot prove."}]}, {"id": "8edf2d5b-8dfd-40d3-8a0a-dcc5aacb9ad2", "type": "topic", "title": "Prediction, machine learning, text-as-data, and policy analytics", "description": "Use predictive models, text data, validation, and model performance metrics responsibly in political and policy contexts.", "children": [{"id": "88a3f347-35c6-45cd-832a-45b3a4cdbbfd", "type": "subtopic", "title": "Prediction workflow", "children": [{"id": "4cf7424d-5f11-40f2-9f9e-920f5fffe181", "type": "concept", "title": "Train/test splits and cross-validation"}, {"id": "f39a2a22-bdf4-4a3b-b56a-14703146993e", "type": "concept", "title": "Performance metrics"}, {"id": "77aaf105-63d8-4bbf-b8b1-e4f614babea5", "type": "concept", "title": "Overfitting and regularization"}], "description": "Students learn how prediction differs from causal explanation."}, {"id": "3563bb39-672f-4e41-a19e-9d8470d74754", "type": "subtopic", "title": "Machine learning models", "children": [{"id": "3c225eb6-3256-4b52-91e5-b5ed63cbbe09", "type": "concept", "title": "Classification, risk scoring, trees, random forests"}, {"id": "6916ca73-e890-4e6f-8350-5bc4f7303d07", "type": "concept", "title": "Threshold choices and calibration"}, {"id": "c5581893-6cae-4df2-a575-4e8f65d3481e", "type": "concept", "title": "Interpretable models and feature importance"}], "description": "This subtopic gives students an applied overview without losing interpretability."}, {"id": "5c746fee-078f-4442-884e-c8f7bc0a6018", "type": "subtopic", "title": "Text-as-data and policy applications", "children": [{"id": "f0885f23-d591-490a-aa3d-c2a7251813f6", "type": "concept", "title": "Tokenization and document-term matrices"}, {"id": "70944b9c-acf3-4d66-bfb6-adb2b192e4be", "type": "concept", "title": "Sentiment, topic models, and supervised text classification"}, {"id": "7d1f074b-aa96-4ad9-bac7-d770abd2688a", "type": "concept", "title": "Text validity and human annotation"}], "description": "Students learn to analyze speeches, platforms, laws, news, comments, and administrative text."}]}, {"id": "0c1452c6-f508-48a1-a8e8-c03c1fcb40a4", "type": "topic", "title": "Data ethics, privacy, fairness, and responsible governance", "description": "Recognize privacy, bias, equity, algorithmic accountability, and research ethics issues in quantitative work.", "children": [{"id": "f2056b69-3eaa-4e8f-ae9c-1f0a78232388", "type": "subtopic", "title": "Research ethics and privacy", "children": [{"id": "02f8e146-af56-42b7-91e6-2cb1411d9e64", "type": "concept", "title": "IRB concepts and informed consent"}, {"id": "2970349e-7120-4409-9961-962dbd0d882a", "type": "concept", "title": "De-identification and re-identification risk"}, {"id": "c8722d26-1e68-40b0-89bb-aa3d6c556d09", "type": "concept", "title": "Data security and access control"}], "description": "Students learn responsibilities that come with human and administrative data."}, {"id": "172de7c7-3ce7-4ebf-8fa7-adf8322f42f8", "type": "subtopic", "title": "Bias and fairness", "children": [{"id": "c9fb34db-02ff-4af0-84e9-2343ce89b5af", "type": "concept", "title": "Historical bias, measurement bias, sample bias"}, {"id": "a3199c8a-a22b-4e28-9282-a00bb1b6384b", "type": "concept", "title": "Fairness metrics and disparate impact awareness"}, {"id": "c0bb5740-3f8a-4165-8fe2-3f0e0812c4e1", "type": "concept", "title": "Equity in policy analytics"}], "description": "This subtopic prepares students to analyze unequal error and harm."}, {"id": "242390ca-9d83-4547-8df6-4a13d62d4e3c", "type": "subtopic", "title": "Responsible data governance", "children": [{"id": "892fed97-1d05-495a-9178-f4e652594959", "type": "concept", "title": "Data minimization and retention"}, {"id": "23ba78bb-e924-46f8-b71d-e50f586e31f4", "type": "concept", "title": "Algorithmic accountability"}, {"id": "a6909b89-b1a2-4041-9f5a-25cf78657205", "type": "concept", "title": "Transparency, auditability, and public trust"}], "description": "Students learn that good analysis includes stewardship, documentation, and accountability."}]}, {"id": "12a0a6e3-191e-4282-ba47-d44fafeb4bbc", "type": "topic", "title": "Communicating evidence, uncertainty, and reproducible policy analysis", "description": "Translate analysis into transparent memos, visualizations, replication packages, and decision-ready recommendations.", "children": [{"id": "2ecd52f6-8df1-4313-9256-1f608a33aa4c", "type": "subtopic", "title": "Policy communication", "children": [{"id": "f70137da-1ee6-49c9-8a89-a24140229b88", "type": "concept", "title": "Executive summaries and policy memos"}, {"id": "bccfbf0d-347a-43c7-a054-c47fc4ac3bde", "type": "concept", "title": "Audience, stakes, and recommendations"}, {"id": "a2289047-5da9-44d4-a420-769b96e7868a", "type": "concept", "title": "Plain-language methods and limitations"}], "description": "Students learn to translate methods into decisions without burying the reader."}, {"id": "2f245e11-46a0-42f5-aa8a-81476f5ae500", "type": "subtopic", "title": "Uncertainty and risk communication", "children": [{"id": "644f2634-a3d3-40f7-9029-fddb5ee94ff2", "type": "concept", "title": "Confidence intervals and prediction intervals"}, {"id": "e54f3ca2-7618-4d41-92cc-6e98b931433e", "type": "concept", "title": "Scenario and sensitivity results"}, {"id": "8f29952a-12a4-4e1b-82cd-7eef9cd197d0", "type": "concept", "title": "Avoiding false precision"}], "description": "This subtopic teaches honest communication of evidence strength."}, {"id": "25923569-f617-4b97-ae02-80c401b791c4", "type": "subtopic", "title": "Final reproducible project", "children": [{"id": "248a8f79-f837-4579-b924-1612b2599a76", "type": "concept", "title": "Question, dataset, analysis plan, and codebook"}, {"id": "609d4c94-c75d-4a96-a34b-26bcf948f38f", "type": "concept", "title": "Reproducible report and replication package"}, {"id": "95182832-f201-4fc8-b2bc-69ce6c4a63e2", "type": "concept", "title": "Oral presentation and peer review"}], "description": "Students finish by integrating data, methods, code, visuals, and interpretation."}]}], "dbBacked": true}$dqmtjson$::jsonb,
